"""Riftbound signature cards, as the monitor watches them."""

from ...catalog import DATA_DIR
from ...game import Game
from ..pokemon.game import ALERT_RULES
from .catalog import CARDS, GAME
from .matcher import RULES
from .tcgplayer import TCGPLAYER


# Every signature card's listing found by narrower searches, such as by set,
# was in this one's results, which reach back about four days.
SEARCHES = ["riftbound signature"]

# Maps catalog card identifiers to PriceCharting product IDs. Generated by
# scripts/map_riftbound_pricecharting.py.
PRODUCT_IDS_PATH = DATA_DIR / GAME / "pricecharting_ids.json"

RIFTBOUND = Game(
    key=GAME,
    name="Riftbound",
    cards=CARDS,
    title_rules=RULES,
    searches=SEARCHES,
    tcgplayer=TCGPLAYER,
    pricecharting_ids_path=PRODUCT_IDS_PATH,
    # The same alert rules as every Pokémon set.
    default_rules=ALERT_RULES,
)
